subjects = ["AI", "ML", "DBMS", "OS", "CN"]
time_slots = ["T1", "T2", "T3"]

conflicts = [
    ("AI", "ML"),
    ("AI", "DBMS"),
    ("ML", "OS"),
    ("DBMS", "CN"),
    ("OS", "CN")
]

def is_valid(subject, slot, assignment):
    for a, b in conflicts:
        if subject == a and b in assignment and assignment[b] == slot:
            return False
        if subject == b and a in assignment and assignment[a] == slot:
            return False
    return True

def backtracking(assignment):
    if len(assignment) == len(subjects):
        return assignment

    for subject in subjects:
        if subject not in assignment:
            for slot in time_slots:
                if is_valid(subject, slot, assignment):
                    assignment[subject] = slot

                    result = backtracking(assignment)

                    if result:
                        return result

                    del assignment[subject]

            return None

solution = backtracking({})

if solution:
    print("Valid Examination Timetable:")
    for subject in subjects:
        print(subject, "->", solution[subject])
else:
    print("No valid timetable found.")

